    RegisterFunctor(CScriptThingFunctor_00ef7ab0(Me));
    Game->NewScriptFrame();
    if (IsDone())
        return;
    CScriptGameResourceObjectScriptedThingBase handle;
    if (handle.IsScripting())
        handle.Release();
    while (!Game->StartScriptingEntity(Me, handle, SCRIPT_AI_PRIORITY_LOW)) {
        Game->NewScriptFrame();
        if (IsDone())
            return;
    }
    IsDone();
}

